record.field:
use_independent = env.company.hlv_barcode_use_independent_permissions
action = False
if use_independent:
    action = env.ref('hlv_mobile_barcode.action_barcode_permission', raise_if_not_found=False)
else:
    action = env.ref('hlv_warehouse_permission.action_warehouse_permission', raise_if_not_found=False)

if action:
    action_dict = action.read()[0]
    action_dict['target'] = 'current'
    action = action_dict
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Không tìm thấy',
            'message': 'Không tìm thấy cấu hình phân quyền phù hợp! Vui lòng kiểm tra lại.',
            'type': 'warning',
            'sticky': False,
        }
    }
